// A LANTERNA: imprimir valores intermediários para achar o desvio.
function somaDaLista(numeros) {
  let soma = 0;
  for (const valor of numeros) {
    console.log('soma antes:', soma, '+', valor); // confira cada volta
    soma = soma + valor;
  }
  return soma;
}

const total = somaDaLista([1, 2, 3]);
console.log('total:', total); // imprime: total: 6

// Passos 1 e 2: as conferências — tipos e divisor.
function dividir(a, b) {
  if (typeof a !== 'number' || typeof b !== 'number') {
    throw new Error('a e b precisam ser números');
  }
  if (b === 0) {
    throw new Error('não é possível dividir por zero');
  }

  // Passo 3: só chegamos aqui com entradas seguras.
  return a / b;
}

// Passo 4: o caminho feliz...
console.log(dividir(10, 2)); // imprime: 5

// ...e o caminho do erro, capturado para o programa continuar.
try {
  console.log(dividir(10, 0)); // lança o erro de divisão por zero
} catch (erro) {
  console.log('Ops:', erro.message); // imprime: Ops: não é possível dividir por zero
}
